    buy_alcohol: {
      id: 'buy_alcohol',
      label: 'Beer or wine',
      location: 'corner_store',
      // Approximation debt (alcohol): base range $4–8; real prices vary by jurisdiction, product,
      // and retailer. col scales from rent as proxy for local price level.
      available: () => getContentLevel() !== 'reduced' && ctx.state.canPurchaseSubstance('alcohol') && ctx.state.canAfford(cornerStorePrice(4)),
      execute: () => {
        const cost = ctx.timeline.randomFloat(cornerStorePrice(4), cornerStorePrice(8));
        const roundedCost = Math.round(cost * 100) / 100;

        if (!ctx.state.spendMoney(roundedCost)) {
          return 'Not enough. You put it back.';
        }

        // One unit (can/bottle) = 1 standard drink in this model.
        ctx.state.set('has_alcohol', ctx.state.get('has_alcohol') + 1);
        ctx.state.advanceTime(ctx.timeline.randomInt(2, 4));
        ctx.state.glanceMoney();

        const mood = ctx.state.moodTone();
        const money = ctx.state.moneyTier();
        const wd = ctx.state.alcoholWithdrawalTier();

        // Appearance — deterministic modifier (layer 3, no RNG). Withdrawal suppresses it.
        // Approximation debt (appearance): NE +3/+6, GABA -2 magnitudes chosen.
        const appearance = ctx.state.appearanceAwareness();
        const withdrawalUrgent = wd === 'moderate' || wd === 'severe' || wd === 'dangerous';
        let appearanceSuffix = '';
        if (!withdrawalUrgent) {
          if (appearance === 'severe') {
            ctx.state.adjustNT('norepinephrine', 6);  // Approximation debt (appearance):
            ctx.state.adjustNT('gaba', -2);            // Approximation debt (appearance):
            ctx.state.adjustNT('serotonin', -2);       // Approximation debt (appearance):
            appearanceSuffix = ' You\'re aware of yourself at the counter. The particular awareness of being seen when you\'re not at your best.';
          } else if (appearance === 'notable') {
            ctx.state.adjustNT('norepinephrine', 3);  // Approximation debt (appearance):
            ctx.state.adjustNT('serotonin', -1);       // Approximation debt (appearance):
          }
        }

        // Withdrawal driving the purchase — DT territory gets its own prose.
        if (wd === 'dangerous') {
          return ctx.timeline.weightedPick([
            { weight: 1, value: 'You get to the register. Pay. You\'re aware of your hands while you do it — aware they\'re not right. The clerk doesn\'t say anything. You walk out.' },
            { weight: 1, value: 'You put it on the counter. Tap your card. The transaction completes. You hold the bottle against your chest on the walk back and count your breaths.' },
          ]);
        }
        if (withdrawalUrgent) {
          return ctx.timeline.weightedPick([
            { weight: 1, value: 'You pay for it. The moment the bottle is in your hand something settles.' },
            { weight: wd === 'severe' ? 2 : 1, value: 'You\'ve been feeling it since you woke up. You pay and put it in your bag and try not to think about why you needed to do that.' },
          ]);
        }

        // Autism camouflaging suffix — deterministic layer-3, no RNG.
        let autismSuffix = '';
        if (ctx.state.get('autism') ?? false) {
          const seTier = ctx.state.socialEnergyTier();
          if (seTier === 'energized' || seTier === 'rested') {
            autismSuffix = ' You read the cashier in a second. Friendly or perfunctory. You match it.';
          } else if (seTier === 'neutral') {
            autismSuffix = ' Hi, thanks, have a good one. The script runs without thinking.';
          } else if (seTier === 'tired') {
            autismSuffix = ' You do the transaction. The script does the work.';
          } else {
            autismSuffix = " You get through the exchange. Something basic and correct. You're not sure what your face was doing.";
          }
        }

        if (money === 'overdrawn') {
          return ctx.timeline.weightedPick([
            { weight: 1, value: 'The account is already negative. You buy it anyway. The number gets worse.' },
            { weight: 1, value: 'You pay. The balance was below zero before this. Now it\'s more below zero.' },
          ]) + appearanceSuffix + autismSuffix;
        }

        if (money === 'broke' || money === 'scraping') {
          return ctx.timeline.weightedPick([
            { weight: 1, value: 'You buy it. The math was already bad. You do the rest of it at home.' },
            { weight: 1, value: 'The money wasn\'t for this. You buy it anyway.' },
          ]) + appearanceSuffix + autismSuffix;
        }

        if (mood === 'numb' || mood === 'hollow') {
          return ctx.timeline.weightedPick([
            { weight: 1, value: 'Beer. You pay. Something to do with your hands later.' },
            { weight: 1, value: 'You buy it without really deciding to.' },
          ]) + appearanceSuffix + autismSuffix;
        }

        return ctx.timeline.weightedPick([
          { weight: 1, value: 'A beer. A bottle of wine. Whatever was closest to the door.' },
          { weight: 1, value: 'You grab something. Pay. The transaction takes about thirty seconds.' },
        ]) + appearanceSuffix + autismSuffix;
      },
    },

