      if (isPastAfternoon && gigEarnings < 20) {
        thoughts.push(
          { weight: 5, value: 'Past two in the afternoon. The day\'s total isn\'t what you needed it to be.' },
          { weight: 4, value: 'You do the math again. The math is not better than last time.' },
        );
      }

